SELECT COUNT(*) FILTER (WHERE sex='M' AND admission='+') AS inpatient_male,
       COUNT(*) FILTER (WHERE sex='M' AND admission='-') AS outpatient_male
FROM patient;

SELECT CASE WHEN COUNT(*) FILTER (WHERE sex='M' AND admission='+') > COUNT(*) FILTER (WHERE sex='M' AND admission='-') THEN 'in-patient' ELSE 'outpatient' END AS more_group,
       ROUND( (COUNT(*) FILTER (WHERE sex='M' AND admission='+')::numeric / NULLIF(COUNT(*) FILTER (WHERE sex='M' AND admission='-'),0)) * 100, 2) AS deviation_percentage
FROM patient;

